return {
  [ [[v5748eaic9qto]] ] = { t = [[变体职业能力与原能力]], q = [[如果某个变体职业把一项职业能力替换为更具体的版本（或运作方式与被取代能力相似的能力），那么对于会提升原能力的规则来说，变体职业的这项能力是否算作原能力？]], a = [=[这取决于变体职业能力的措辞。如果变体职业能力说它的运作方式与标准能力相同，它就算作该能力。如果变体职业能力要求你为标准能力做出某项特定选择，它也算作该能力。除此之外，变体职业能力不算作标准能力。（变体职业能力的名称是否与它所取代的标准职业能力不同并不重要，起决定作用的是变体职业能力的描述和游戏机制。）

举例：[[龙骑兵]]（《极限战斗》中的战士变体职业）拥有名为【枪矛训练】的能力，它要求龙骑兵选择“矛类”作为他的武器训练组，并涉及他的武器训练加值（尽管这个加值的提升进度与标准武器训练略有不同）。因此，对于提升武器训练的能力来说，例如会提升穿戴者武器训练加值的[[决斗手套]]（《进阶玩家指南》），这项能力算作武器训练。

举例：[[弓手]]（战士变体职业）获得了数项取代武器训练的能力（例如【射击专家】），它们并未另行提及武器训练能力。因此，对于提升武器训练的能力（例如决斗手套）来说，这些能力不算作武器训练。即使是【射击专家】这种加值每4个战士等级提升一次、与武器训练完全一样的能力，也是如此。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qto]], cat = [[FAQ]], ai = false, pages = { [[变体职业]] } },
  [ [[v5748eaic9qw9]] ] = { t = [[甲刺与副手攻击]], q = [[如果我在同一轮里使用双手武器，能用双武器战斗规则以甲刺发动一次“副手”攻击吗？]], a = [=[不能。

同样，你也无法用[[铁手套]]这样做，因为你的双手都在握持双手武器，所以你的副手无法进行任何攻击。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qw9]], cat = [[FAQ]], ai = false, pages = { [[甲刺(防具)]], [[甲刺(武器)]] } },
  [ [[v5748eaic9qv4]] ] = { t = [[重击与确认重击]], q = [=[“打出[[重击]]”与“确认重击”有区别吗？]=], a = [[没有，两者意思相同。不过，规则用语上更推荐“确认重击”。（同样，掷出重击威胁的推荐用语是“造成重击威胁”。）]], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qv4]], cat = [[FAQ]], ai = false, pages = { [[战斗中的动作]], [[重击]] } },
  [ [[v5748eaic9uxg]] ] = { t = [[武器攻击与特殊能力]], q = [[规则中许多地方使用“远程武器攻击”及类似用语，但这对需要远程攻击、却未必像是武器的法术、类法术能力、超自然能力和特异能力（以下统称特殊能力）如何适用？]], a = [=[一般而言，需要攻击检定的特殊能力会受到所有影响攻击检定的调整值的利弊影响，即使这些调整值提到的是武器攻击检定（例如向近战中的目标射击的减值、来自[[近距射击]]和激发勇气的攻击检定加值，等等），除非法术明确说明它不适用这些调整值（例如[[灵能武器]]明确说明它不受专长和战斗动作影响，但如果是远程攻击，它仍然要应对掩蔽，以及向近战中的目标射击）。

对于影响武器伤害掷骰或单纯“伤害掷骰”的调整值（例如来自近距射击、激发勇气和制裁邪恶的伤害掷骰加值），在成功的攻击检定后造成伤害的特殊能力只对生命值伤害应用它们，并且每次施放或使用只应用一次，而不是每次攻击一次。例如，如果一个法术或特殊能力同时发射了十几次不同的远程攻击，那么只有一次（由使用者选择）能获得额外伤害。这不适用于偶有额外攻击检定可能的区域效果，如[[火球术]]。不过，有一类能力需要特别注意：像[[奥术打击]]这样专门强化角色武器本身的能力，从不适用于特殊能力（除非像魔导师的秘法弹这样的特殊能力明确说明奥术打击适用）。

与奥术打击这类影响角色武器的能力同理，写着“用武器”“用近战武器”和“用远程武器”的能力几乎从不对特殊能力生效，因为这种措辞几乎总是“人造武器”“人造近战武器”和“人造远程武器”的简略说法。例外是当生物触碰你或在近战中击中你时造成伤害的能力（例如秘学士的“能量守卫”灵器之力），当生物对你进行近战接触攻击时，它们也应当造成伤害，只是很少会直接点明。

某些特殊能力（例如射线、念袭和秘法弹）可以专门被[[武器专攻]]和[[精通重击]]这样的专长选择。它们在其他规则中仍然不被视为一种武器：它们不属于任何武器组，也不符合战士的武器训练、战斗祭司的神圣武器、魔战士的奥能力池、圣武士的神契或其他任何类似能力的作用条件。

改变远程武器攻击动作用法的能力，或需要使用自己专门动作的能力，几乎从不对特殊能力生效，因为特殊能力需要自己的动作。例如，[[精确瞄准]]对[[灼热射线]]或音爆强袭者的【怪异之音】无效，因为它们各自都需要用自己的动作来启动，因此无法成为该专长所规定的那个标准动作的一部分。少数例外包括秘法弹和念刃，它们可以明确地作为其他动作的一部分来使用。]=], book = [[核心规则书]], date = [[2016/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9uxg]], cat = [[FAQ]], ai = true, pages = { [[战斗中的动作]], [[魔法]] } },
  [ [[v5748eaic9vn2]] ] = { t = [[自然20与自然1]], q = [[在攻击检定和豁免检定中，自然20自动成功，自然1自动失败。但在判断检定是否以5点或更多的差距成功或失败、比较两个对抗攻击检定哪个结果更高，或其他类似情形时，我是否应当区别对待它们？]], a = [=[不需要。除非有特定规则另行说明，在把总结果与其他数值比较时，攻击检定或豁免检定上的自然20或自然1应当与其他结果同样处理。例如，一名战士掷出自然1，总结果为31，对抗法师33点的AC，那么这次攻击未命中的差距不足5点，会毁掉法师[[镜影术]]的一个镜像。]=], book = [[核心规则书]], date = [[2017/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vn2]], cat = [[FAQ]], ai = true, pages = { [[战斗中的数据计算]] } },
  [ [[v5748eaic9qdc]] ] = { t = [[远程接触攻击法术与借机攻击]], q = [=[当我施放一个允许进行远程接触攻击的法术（例如[[灼热射线]]），而敌人就在我的触及范围内时，我会引发两次借机攻击吗？]=], a = [[是的，你会引发两次借机攻击：一次因为施放法术，一次因为进行远程攻击，因为这是两个独立的事件。

（注意，像灼热射线这样同时发射多条射线的法术，只会因进行远程攻击引发一次借机攻击，而不是每次远程攻击各引发一次。它仍然会因为施放法术而引发借机攻击。）

这个回答最初发表于2012年9月11日的Paizo博客。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qdc]], cat = [[FAQ]], ai = false, pages = { [[战斗中的数据计算]] } },
  [ [[v5748eaic9qd5]] ] = { t = [[触及与物体]], q = [[你能拾起或操作处于你触及范围内某个方格里的物体吗？这会引发借机攻击吗？如果对手能触及物体、却触及不到你所在的空间，也会引发吗？]], a = [[规则在这里有些含糊，但简单来说，你可以影响处于你触及范围内的物体和生物。拾起或操作物体通常会引发借机攻击，但只针对能触及你所在空间的敌人。无论你采取什么行动，即使它包括把手伸进受威胁的空间，你也不会对触及不到你的敌人引发借机攻击。虽然在这种情况下允许一次攻击看起来也许更真实，但那会让游戏变得过于复杂。

这个回答最初发表于2012年9月25日的Paizo博客。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qd5]], cat = [[FAQ]], ai = false, pages = { [[战斗中的数据计算]], [[战斗中的动作]] } },
  [ [[v5748eaic9rb0]] ] = { t = [[行动受限的即时生效]], q = [[如果借机攻击或其他打断效果减少了我在自己回合内能采取的动作，这种减少会立即生效吗？]], a = [=[会，即使它打断或限制了你正在进行的行动。

例如，你正在进行整轮攻击并试图摔绊对手，但因为你没有[[精通摔绊]]而引发了借机攻击，而对手的[[储法(武器附魔)|储法]]武器里储存了[[人类定身术]]，你的豁免失败，那么你会立即被麻痹，无法采取任何剩余的动作（包括整轮攻击的其余部分）。

同样，如果你的对手拥有[[恍惚重击]]专长而不是储法武器，并且那次攻击使你陷入恍惚，你会立即获得恍惚状态，这会使你无法采取任何违反恍惚状态限制的动作。如果你是因为采取移动动作穿过对手的威胁区域而引发借机攻击，你可以完成这个移动动作，但不能在它之后再采取标准动作。如果你是在整轮攻击期间引发的借机攻击（如摔绊的例子），陷入恍惚会在此处结束你的整轮攻击，并使你无法在这次造成恍惚的攻击之后再采取移动动作。无论借机攻击是因为你整轮攻击中的第一次攻击还是你最后一次允许的攻击而发生，恍惚都会在那一刻结束你的整轮攻击，因为陷入恍惚时你无法进行整轮攻击。]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rb0]], cat = [[FAQ]], ai = false, pages = { [[战斗中的数据计算]], [[战斗中的动作]] } },
  [ [[v5748eaic9sp8]] ] = { t = [[10尺触及与对角方格]], q = [[我对触及和对角方格感到困惑。我在网上听说，拥有10尺触及时你并不威胁第二个对角方格，但当对手离开那个方格时你又能以某种方式获得借机攻击；可是规则参考卡显示你确实威胁第二个对角方格。哪个才是对的？]], a = [[卡片是正确的。作为对角线通常运作方式的例外，拥有10尺触及的生物威胁第二个对角方格。这些改动将反映在下次勘误中。]], book = [[核心规则书]], date = [[2014/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9sp8]], cat = [[FAQ]], ai = false, pages = { [[战斗中的数据计算]] } },
  [ [[v5748eaic9rbq]] ] = { t = [[增强召唤与类法术能力]], q = [=[这项专长对用[[召唤怪物]]或[[召唤自然盟友]]类法术能力召唤的怪物有效吗？]=], a = [[有效。]], book = [[核心规则书]], date = [[2013/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rbq]], cat = [[FAQ]], ai = false, pages = { [[增强召唤]] } },
  [ [[v5748eaic9ncy]] ] = { t = [[启蒙术与魔法兽类型]], q = [=[把生物的类型改为“[[魔法兽]]”会影响它的生命骰类型、BAB或其他特性吗？它额外获得的2个生命骰呢？训练穿着坐骑护甲与防具擅长有什么关系？]=], a = [[只有该动物的类型变为“魔法兽”——它并不会获得这一类型变化带来的全部数值上的收益（可以把它看作给生物添加模板的“简易规则”版本）。

它获得的2个生命骰是d8，和它其他的动物生命骰一样。

受过训练穿着坐骑护甲的动物，在被启蒙之后仍然可以无减值地继续穿着。被启蒙之后，它可以像任何智慧生物一样，花一个专长获得防具擅长，或获得提供防具擅长的职业的职业等级。]], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ncy]], cat = [[FAQ]], ai = true, pages = { [[启蒙术]] } },
  [ [[v5748eaic9rdl]] ] = { t = [[破敌的叠加]], q = [=[我能在同一把武器上附加多个[[破敌]]特殊能力吗？如果可以，它们的效果会叠加吗？]=], a = [=[你可以在同一把武器上附加多个破敌特殊能力。例如，你可以拥有一把+1破敌（龙、精类）长剑，它在对付龙和精类时都有提高的增强加值和额外伤害。

如果武器带有多个破敌效果，而你攻击的生物同时符合其中不止一种破敌（例如用混乱异界生物与邪恶异界生物破敌武器对付恶魔），这些效果不会叠加：武器的增强加值只比它实际的增强加值高+2，对该对手也只额外造成+2d6点伤害。

（对比[[战士#武器训练|战士的武器训练]]或游侠的宿敌加值，这两者都说明当不止一项加值适用时使用最高的加值。）]=], book = [[核心规则书]], date = [[2013/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rdl]], cat = [[FAQ]], ai = false, pages = { [[破敌]] } },
  [ [[v5748eaic9t8o]] ] = { t = [[博学与取10]], q = [=[我能在[[知识]]检定上取10吗？知识技能没说不行，但如果真是这样，[[吟游诗人]]【博学】能力的前半句就毫无作用了。]=], a = [[可以。【博学】能力应当在第一句末尾加上“即使受到威胁或分心”。]], book = [[核心规则书]], date = [[2015/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t8o]], cat = [[FAQ]], ai = true, pages = { [[吟游诗人]] } },
  [ [[v5748eaic9rb5]] ] = { t = [[重剑是单手还是双手武器]], q = [[重剑是单手武器还是双手武器？]], a = [=[重剑是单手武器（尽管在某些规则里，它模糊了单手与双手武器之间的界线）。

重剑的物理属性是单手武器的属性。例如，它的硬度、生命值、能否以特殊材料制作、手艺技能的制作类别、[[炼银]]的效果等等，都按单手武器处理。

对于随你使用单手武器、双手武器还是双手持用单手武器而变化、或明确依赖于此的职业能力、专长和其他规则要素，重剑按你实际用了几只手来持用它而计。

例如，如果你单手持用它（通常需要[[擅长异种武器]]专长），它被视为单手武器；[[猛力攻击]]只能获得单手武器的加值，你不能使用[[推进强袭]]或[[剑刃屏障]]（它们要求双手武器），等等。

如果你双手持用它（无论你是否拥有单手持用它所需的擅长异种武器），它被视为双手武器；猛力攻击能获得更高的伤害加值，你可以使用推进强袭或剑刃屏障（它们要求双手武器），等等。

持用手数规则的一个特殊情况是，有些能力允许你把双手武器视为单手武器。例如，巨人杀手（野蛮人变体职业）的约顿之握（允许你单手持用双手武器）让你即使没有擅长异种武器也能单手持用重剑，并且（如该能力所述）把它视为单手武器，因此在其他效果上它也被视为单手武器。]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rb5]], cat = [[FAQ]], ai = false, pages = { [[重剑]] } },
  [ [[v5748eaic9t0g]] ] = { t = [[大型生物与以自身为中心的效果]], q = [[如果大型或更大的生物使用了“以你为中心”的效果，这是否意味着有时那个弥漫效果连该生物自己的整个占据空间都覆盖不到，更别说其他东西了？]], a = [=[不会。当这样的生物使用带有“以你为中心”字样的弥漫或爆发时，把该生物的整个占据空间视为法术的源起点，并从该生物占据空间的边缘开始量度法术的区域或效果。例如，一条远古红龙施放的[[反魔场]]会延伸到她30×30尺的占据空间之外10尺，总直径为50尺。]=], book = [[核心规则书]], date = [[2015/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t0g]], cat = [[FAQ]], ai = true, pages = { [[不同体型生物的战斗]], [[魔法]] } },
}